export const ORBIT_THEMES = [
    { value: 'd-grey', title: 'Dark Grey (d-grey)' },
    { value: 'd-green', title: 'Dark Green (d-green)' },
    { value: 'n-grey', title: 'Neutral Grey (n-grey)' },
    { value: 'n-green', title: 'Neutral Green (n-green)' },
    { value: 'n-blue', title: 'Neutral Blue (n-blue)' },
];
// Served via Storybook `staticDirs`: `{ from: './themes', to: '/orbit-themes' }`.
export const ORBIT_THEME_STYLES = {
    'd-grey': '/orbit-themes/d-grey.css',
    'd-green': '/orbit-themes/d-green.css',
    'n-grey': '/orbit-themes/n-grey.css',
    'n-green': '/orbit-themes/n-green.css',
    'n-blue': '/orbit-themes/n-blue.css',
};
export const DEFAULT_ORBIT_THEME = 'd-grey';
const THEME_LINK_ID = 'orbit-storybook-theme';
export function applyOrbitTheme(themeId) {
    const href = ORBIT_THEME_STYLES[themeId] ?? ORBIT_THEME_STYLES[DEFAULT_ORBIT_THEME];
    let link = document.getElementById(THEME_LINK_ID);
    if (!link) {
        link = document.createElement('link');
        link.id = THEME_LINK_ID;
        link.rel = 'stylesheet';
        document.head.appendChild(link);
    }
    if (link.href !== href) {
        link.href = href;
    }
}
